import{_ as t,o as a,c as r,a2 as d}from"./chunks/framework.BEUshCVJ.js";const p=JSON.parse('{"title":"隐私与数据","description":"","frontmatter":{},"headers":[],"relativePath":"zh/reference/privacy.md","filePath":"zh/reference/privacy.md","lastUpdated":1793120225000}'),o={name:"zh/reference/privacy.md"};function i(l,e,c,n,s,h){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="隐私与数据" tabindex="-1">隐私与数据 <a class="header-anchor" href="#隐私与数据" aria-label="Permalink to &quot;隐私与数据&quot;">​</a></h1><p>本页说明 MeetCue 会把什么发给哪家供应商、在你的电脑上保存什么，以及哪些数据永远不会收集。MeetCue 没有自己的服务器：一切都在你的电脑上运行，用你自己的密钥直接连接你选择的供应商。</p><h2 id="发给语音识别供应商的内容" tabindex="-1">发给语音识别供应商的内容 <a class="header-anchor" href="#发给语音识别供应商的内容" aria-label="Permalink to &quot;发给语音识别供应商的内容&quot;">​</a></h2><ul><li>拾取开启期间，麦克风和系统声音的音频，转换为 16 kHz 单声道。静音部分不发送，但说话开始前约 0.3 秒会一并发送，以免截掉第一个字；说话结束后约一秒内的静音也会发送，以便识别服务判断一句话已经说完。</li><li>会前资料中的术语，作为识别热词。</li><li>练习模式关闭 <strong>问题语音转文字</strong> 时，不发送对方的音频。</li></ul><h2 id="发给大模型供应商的内容" tabindex="-1">发给大模型供应商的内容 <a class="header-anchor" href="#发给大模型供应商的内容" aria-label="Permalink to &quot;发给大模型供应商的内容&quot;">​</a></h2><ul><li>问题检测：识别出的句子和前后几句上下文。</li><li>要点生成：问题、最近的对话、你的角色，以及会前资料的一小段摘录。</li><li>练习模式：题目、识别出的你的回答、用于反馈的参考回答，以及需要分类的字幕句子。</li><li>延迟探测：一小段内置的示例转写。</li></ul><h2 id="价格查询" tabindex="-1">价格查询 <a class="header-anchor" href="#价格查询" aria-label="Permalink to &quot;价格查询&quot;">​</a></h2><p>为估算用量费用和预算，MeetCue 会在启动时读取 Anthropic、Soniox、Deepgram 的公开价格页，以及本站的<a href="/meetcue/zh/reference/pricing">价格参考</a>。这些只是普通的网页下载，不会发送任何密钥、账号或会议内容。</p><p>你发给各供应商的数据适用其各自的隐私政策和数据保留条款。在保密会议中使用 MeetCue 之前，请先查阅这些条款。</p><h2 id="保存在你电脑上的内容" tabindex="-1">保存在你电脑上的内容 <a class="header-anchor" href="#保存在你电脑上的内容" aria-label="Permalink to &quot;保存在你电脑上的内容&quot;">​</a></h2><table tabindex="0"><thead><tr><th>数据</th><th>位置</th></tr></thead><tbody><tr><td>API 密钥</td><td>Windows 凭据管理器中名为 <code>MeetCue</code> 的条目</td></tr><tr><td>设置、角色和抽取的会前资料文字</td><td>设置文件夹中的 <code>settings.json</code></td></tr><tr><td>延迟探测结果</td><td><code>latency-history.json</code></td></tr><tr><td>每次调用的用量与费用（不含内容）</td><td><code>usage.jsonl</code></td></tr><tr><td>日志，保留 7 天；除非开启调试日志，否则不含转写（最近的内容也显示在 <strong>设置 › 诊断 › 运行日志</strong> 中）</td><td><code>logs\\</code></td></tr><tr><td>最近一份价格表，供离线使用</td><td><code>pricing.json</code></td></tr><tr><td>练习报告</td><td><code>practice\\</code></td></tr></tbody></table><p>设置文件夹的位置见<a href="/meetcue/zh/reference/settings#where-settings-are-stored">设置项</a>。音频永远不会写入磁盘。</p><h2 id="meetcue-不会做的事" tabindex="-1">MeetCue 不会做的事 <a class="header-anchor" href="#meetcue-不会做的事" aria-label="Permalink to &quot;MeetCue 不会做的事&quot;">​</a></h2><ul><li>不收集遥测、使用统计或崩溃报告。</li><li>API 密钥不会传给界面，不会写入文件，也不会写进日志。</li><li>导出的诊断信息不包含密钥、转写、会前资料或练习记录。</li><li>拾取暂停期间不会向任何地方发送数据，你主动运行的延迟探测除外。</li></ul><h2 id="删除你的数据" tabindex="-1">删除你的数据 <a class="header-anchor" href="#删除你的数据" aria-label="Permalink to &quot;删除你的数据&quot;">​</a></h2><ol><li>用 <code>scoop uninstall meetcue --purge</code> 卸载，同时删除设置文件夹。</li><li>在 <strong>凭据管理器 › Windows 凭据</strong> 中删除名为 <code>MeetCue</code> 的条目。</li><li>按各供应商的政策，请他们删除保留的数据。</li></ol>',16)])])}const f=t(o,[["render",i]]);export{p as __pageData,f as default};
